function sideChatSessions(){return state.sessions.filter((item)=>item.projectId===state.activeProjectId&&!item.archivedAt);}
function renderSideChat(){
  const select=byId('side-chat-session'),root=byId('side-chat-messages');if(!select||!root)return;
  const sessions=sideChatSessions();if(state.sideChatSessionId&&!sessions.some((item)=>item.id===state.sideChatSessionId))state.sideChatSessionId=null;
  if(!state.sideChatSessionId)state.sideChatSessionId=sessions.find((item)=>item.id!==state.activeSessionId)?.id??sessions[0]?.id??null;
  clear(select);for(const session of sessions)appendOption(select,session.id,`${session.name} · ${session.runtimeType}`,session.id===state.sideChatSessionId);
  if(!sessions.length)appendOption(select,'','暂无可用 Agent Session',true);
  select.disabled=!sessions.length;byId('side-chat-input').disabled=!sessions.length;
  const send=byId('side-chat-form').querySelector('button[type="submit"]');send.disabled=!sessions.length;
  clear(root);const session=state.sessions.find((item)=>item.id===state.sideChatSessionId);
  if(!session){root.append(emptyText('新建 Agent Session 后可在这里并行对话'));setText('side-chat-status','');return;}
  setText('side-chat-status',statusLabel(session.status));
  const messages=[];
  for(const event of state.recentEvents.filter((item)=>item.sessionId===session.id)){
    if(event.type==='user.message')messages.push({kind:'user',label:'你',text:String(event.payload.text??'')});
    else if(event.type==='assistant.delta'){
      const last=messages[messages.length-1];if(last?.kind==='assistant')last.text+=String(event.payload.text??'');else messages.push({kind:'assistant',label:session.runtimeType==='claude'?'Claude Code':'Codex',text:String(event.payload.text??'')});
    }else if(event.type==='tool.event')messages.push({kind:'tool',label:String(event.payload.tool??'Tool'),text:String(event.payload.summary??event.payload.phase??'')});
    else if(event.type==='runtime.error')messages.push({kind:'error',label:'Runtime error',text:String(event.payload.message??'未知错误')});
  }
  for(const message of messages.slice(-40)){const node=messageNode(message.kind,message.label,message.text);node.classList.add('side-chat-message');root.append(node);}
  if(!root.children.length)root.append(emptyText('这个 Agent 尚无消息'));root.scrollTop=root.scrollHeight;
}
async function sendSidePrompt(event){event.preventDefault();const session=state.sessions.find((item)=>item.id===state.sideChatSessionId),input=byId('side-chat-input'),text=input.value.trim();if(!session||!text)return;if(session.importedReadOnly){setText('side-chat-status','导入历史为只读；请在主会话中 Fork');return;}const original=input.value;input.value='';setText('side-chat-status','正在发送…');try{operationError(await window.tsukiori.workspace.sendPrompt(session.id,text));setText('side-chat-status','已发送');}catch(error){input.value=original;setText('side-chat-status',error.message);}}

