const teamRoleDefaults=['架构与实现','测试与审查','文档与体验','安全与集成'];
function bindTeamAgentSection(section){if(section.dataset.bound==='true')return;section.dataset.bound='true';section.querySelector('[data-team-runtime]').addEventListener('change',()=>updateTeamAgent(section));section.querySelector('[data-team-provider]').addEventListener('change',()=>fillModels(section.querySelector('[data-team-model]'),section.querySelector('[data-team-provider]').value));section.querySelector('[data-team-remove]').addEventListener('click',()=>{if(document.querySelectorAll('[data-team-agent]').length<=2)return;section.remove();reindexTeamAgents();});}
function reindexTeamAgents(){const sections=[...document.querySelectorAll('[data-team-agent]')];sections.forEach((section,index)=>{section.dataset.teamAgent=String(index);section.querySelector('[data-team-agent-title]').textContent=`Agent ${String.fromCharCode(65+index)}`;const remove=section.querySelector('[data-team-remove]');remove.disabled=sections.length<=2;remove.setAttribute('aria-label',`移除 Agent ${String.fromCharCode(65+index)}`);});setText('team-agent-count',`${sections.length} / 4 成员`);byId('team-agent-add').disabled=sections.length>=4;}
function addTeamAgent(){const sections=[...document.querySelectorAll('[data-team-agent]')];if(sections.length>=4)return;const section=sections[0].cloneNode(true),index=sections.length;section.dataset.bound='false';section.querySelector('[data-team-role]').value=teamRoleDefaults[index]??`Agent ${index+1}`;for(const select of section.querySelectorAll('select'))clear(select);byId('team-agent-grid').append(section);bindTeamAgentSection(section);updateTeamAgent(section,true);reindexTeamAgents();}
function openTeamDialog(){if(!activeProject()){setText('onboarding-status','请先添加本地 Git 项目');return;}const sections=[...document.querySelectorAll('[data-team-agent]')];for(const section of sections.slice(2))section.remove();[...document.querySelectorAll('[data-team-agent]')].forEach((section,index)=>{section.querySelector('[data-team-role]').value=teamRoleDefaults[index];bindTeamAgentSection(section);updateTeamAgent(section,true);});reindexTeamAgents();showDialog(byId('team-dialog'));}
function updateTeamAgent(section,reset=false){const runtime=section.querySelector('[data-team-runtime]');const provider=section.querySelector('[data-team-provider]');const model=section.querySelector('[data-team-model]');if(reset||!runtime.children.length)fillRuntime(runtime,runtime.value||state.settings.defaultRuntime||'codex');fillProvider(provider,runtime.value,provider.value||state.settings.defaultProviderId);fillModels(model,provider.value,model.value||state.settings.defaultModel);}
async function createTeam(event){event.preventDefault();if(event.submitter?.value==='cancel'){dismissDialog(byId('team-dialog'),'team-create-status');return;}const project=activeProject();if(!project)return;const agents=[...document.querySelectorAll('[data-team-agent]')].map((section)=>({role:section.querySelector('[data-team-role]').value,runtimeType:section.querySelector('[data-team-runtime]').value,providerId:section.querySelector('[data-team-provider]').value,model:section.querySelector('[data-team-model]').value}));setText('team-create-status','正在创建独立 Worktree 并派发…');try{const result=operationError(await window.tsukiori.workspace.createTeam(project.id,byId('team-goal').value,agents));state.selectedTeamId=result.team.id;byId('team-dialog').close();byId('team-goal').value='';await reloadSnapshot();activateWorkPanel('chat');}catch(error){setText('team-create-status',error.message);} }

async function ensureTerminal(sessionId){if(state.terminalSessionId===sessionId)return;if(state.terminalSessionId){await window.tsukiori.workspace.stopTerminal(state.terminalSessionId).catch(()=>undefined);}state.terminalSessionId=sessionId;setText('terminal-output','正在启动 PowerShell…\n');try{operationError(await window.tsukiori.workspace.startTerminal(sessionId,120,28));}catch(error){setText('terminal-output',error.message);} }
async function restartTerminal(){const session=activeSession();if(!session)return;try{if(state.terminalSessionId){await window.tsukiori.workspace.stopTerminal(state.terminalSessionId).catch(()=>undefined);state.terminalSessionId=null;}setText('terminal-output','正在重启 PowerShell…\n');await ensureTerminal(session.id);byId('terminal-input').focus();}catch(error){setText('terminal-output',error.message);} }

async function attachFiles(){const session=activeSession();if(!session)return;try{const result=operationError(await window.tsukiori.workspace.pickAttachments(session.id));if(result.canceled)return;state.attachments.push(...(result.attachments??[]));renderAttachments();await refreshFiles();}catch(error){setText('turn-status',error.message);} }
function renderAttachments(){const root=byId('composer-attachments');clear(root);for(const attachment of state.attachments){const chip=document.createElement('span');chip.className='attachment-chip';chip.textContent=attachment.path;root.append(chip);}root.hidden=state.attachments.length===0;}

async function refreshFiles(){const session=activeSession();if(!session)return;try{const result=operationError(await window.tsukiori.workspace.listFiles(session.id,byId('file-query').value));renderFileList(result.files??[]);}catch(error){setText('file-preview',error.message);} }
function renderFileList(files){const root=byId('panel-file-list');clear(root);for(const file of files){const row=document.createElement('button');row.type='button';row.className='panel-file';row.append(Object.assign(document.createElement('span'),{textContent:'▧'}),Object.assign(document.createElement('span'),{textContent:file.path}),Object.assign(document.createElement('small'),{textContent:formatBytes(file.size)}));row.addEventListener('click',()=>void loadFilePreview(file.path,row));root.append(row);}if(!files.length)root.append(emptyText('没有匹配的文件'));}
async function loadFilePreview(path,row){const session=activeSession();if(!session)return;try{const result=operationError(await window.tsukiori.workspace.readFile(session.id,path));state.filePreviewContent=result.file.content;setText('file-preview-name',result.file.path+(result.file.truncated?' · 已截断':''));setText('file-preview',result.file.content);for(const item of byId('panel-file-list').children)item.classList.toggle('active',item===row);}catch(error){state.filePreviewContent='';setText('file-preview-name',path);setText('file-preview',error.message);} }

async function loadCodexNative(){const session=activeSession(),root=byId('native-capability-list');if(!session){state.extensionHealth=null;clear(root);root.append(emptyText('请选择 Session'));return;}clear(root);root.append(emptyText('正在对照宿主配置与 Runtime 实际观察…'));try{const result=operationError(await window.tsukiori.workspace.extensionHealth(session.id));state.extensionHealth=result.health;clear(root);for(const server of result.health.mcp??[])root.append(capabilityItem('MCP · '+server.name,`${server.configuredScope} → ${server.runtimeScope} · ${server.runtimeAuthStatus} · ${server.toolCount} tools`,server.health));for(const skill of result.health.skills??[])root.append(capabilityItem('Skill · '+skill.name,`${skill.configuredScope} → ${skill.runtimeScope} · ${skill.description||skill.source}`,skill.health));for(const limitation of result.health.limitations??[])root.append(capabilityItem('能力边界',limitation,result.health.supportLevel));if(!root.children.length)root.append(emptyText('当前 Session 未发现 Skills 或 MCP'));renderMcpSettings();renderSkillsSettings();}catch(error){state.extensionHealth=null;clear(root);root.append(emptyText(error.message));} }

async function renameActiveSession(){const session=activeSession();if(!session)return;const name=window.prompt('新的 Session 名称',session.name);if(name===null)return;try{operationError(await window.tsukiori.workspace.renameSession(session.id,name));await reloadSnapshot();}catch(error){setText('turn-status',error.message);} }
async function pinActiveSession(){const session=activeSession();if(!session)return;try{operationError(await window.tsukiori.workspace.pinSession(session.id,!session.pinned));await reloadSnapshot();}catch(error){setText('turn-status',error.message);} }
async function archiveActiveSession(){const session=activeSession();if(!session)return;if(!window.confirm('归档此 Session？独立 Worktree 会保留，不会删除未提交代码。'))return;try{if(state.terminalSessionId===session.id){await window.tsukiori.workspace.stopTerminal(session.id);state.terminalSessionId=null;}operationError(await window.tsukiori.workspace.archiveSession(session.id));state.activeSessionId=null;await reloadSnapshot();}catch(error){setText('turn-status',error.message);} }
async function forkActiveSession(){const session=activeSession();if(!session)return;if(!window.confirm('Fork 会复制 Claude 对话历史，并从当前已提交代码创建独立 Worktree。未提交变更不会被复制；继续？'))return;try{setText('turn-status','正在创建 Claude Fork…');const result=operationError(await window.tsukiori.workspace.forkSession(session.id));state.activeSessionId=result.session.id;await reloadSnapshot();}catch(error){setText('turn-status',error.message);} }
function scheduleSessionSearch(){if(state.sessionSearchTimer)clearTimeout(state.sessionSearchTimer);state.sessionSearchResults=new Map();renderNavigation();const query=byId('history-query').value.trim();if(!query)return;state.sessionSearchTimer=setTimeout(async()=>{try{const responses=await Promise.all(state.projects.map((project)=>window.tsukiori.workspace.searchSessions(project.id,query)));if(query!==byId('history-query').value.trim())return;const results=responses.flatMap((response)=>operationError(response).results??[]);state.sessionSearchResults=new Map(results.map((item)=>[item.sessionId,item]));renderNavigation();}catch(error){setText('turn-status',error.message);}},150);}

function renderCheckpoints(){const root=byId('checkpoint-list');if(!root)return;clear(root);for(const checkpoint of state.checkpoints){const row=document.createElement('article');row.className='checkpoint-row '+(checkpoint.kind==='recovery'?'recovery':'manual');const copy=document.createElement('div');const strong=document.createElement('strong');strong.textContent=checkpoint.label;const meta=document.createElement('small');meta.textContent=`${checkpoint.kind==='recovery'?'恢复点':'手动'} · ${new Date(checkpoint.createdAt).toLocaleString()} · ${checkpoint.conversationEventCount} events`;copy.append(strong,meta);const rewind=document.createElement('button');rewind.type='button';rewind.textContent='预览并回退';rewind.addEventListener('click',()=>void rewindToCheckpoint(checkpoint.id));row.append(copy,rewind);root.append(row);}if(!root.children.length)root.append(emptyText('暂无 Checkpoint'));}
async function refreshCheckpoints(){const session=activeSession();if(!session){state.checkpoints=[];renderCheckpoints();return;}try{const result=operationError(await window.tsukiori.workspace.listCheckpoints(session.id));state.checkpoints=result.checkpoints??[];renderCheckpoints();}catch(error){state.checkpoints=[];renderCheckpoints();setText('checkpoint-status',error.message);}}
async function createActiveCheckpoint(){const session=activeSession();if(!session)return;const input=byId('checkpoint-label');const label=input.value.trim()||`Checkpoint ${new Date().toLocaleTimeString()}`;try{setText('checkpoint-status','正在保存对话、Index 与 Worktree…');operationError(await window.tsukiori.workspace.createCheckpoint(session.id,label));input.value='';setText('checkpoint-status','Checkpoint 已创建');await refreshCheckpoints();await refreshGit();}catch(error){setText('checkpoint-status',error.message);}}
async function rewindToCheckpoint(checkpointId){const session=activeSession();if(!session)return;try{const preview=operationError(await window.tsukiori.workspace.previewCheckpoint(session.id,checkpointId)).preview;const sample=(preview.changedPaths??[]).slice(0,8).join('\n');const message=`将回退 ${preview.changedPathCount} 个代码路径，并移除 ${preview.conversationEventsRemoved} 个后续对话事件。\n分支 HEAD 不会移动；操作前会自动创建恢复点。${sample?'\n\n影响示例：\n'+sample:''}\n\n确认继续？`;if(!window.confirm(message))return;setText('checkpoint-status','正在创建恢复点并回退…');const result=operationError(await window.tsukiori.workspace.rewindCheckpoint(session.id,checkpointId)).result;setText('checkpoint-status',`已回退；恢复点 ${result.recoveryCheckpoint.id}`);await reloadSnapshot();await refreshCheckpoints();await refreshGit();}catch(error){setText('checkpoint-status',error.message);await refreshCheckpoints();}}

function setRightPanelOpen(open){const shell=document.querySelector('.app-shell');shell.classList.toggle('right-collapsed',!open);for(const id of ['toggle-right-panel','header-work-panel'])byId(id)?.setAttribute('aria-pressed',String(open));}
function setLeftPanelOpen(open){const shell=document.querySelector('.app-shell');shell.classList.toggle('left-collapsed',!open);byId('toggle-left-panel')?.setAttribute('aria-pressed',String(open));}
function setTerminalOpen(open){const shell=document.querySelector('.app-shell');shell.classList.toggle('terminal-collapsed',!open);byId('toggle-terminal')?.setAttribute('aria-pressed',String(open));byId('terminal-collapse')?.setAttribute('aria-label',open?'收起终端':'展开终端');}
function activateWorkPanel(name){
  const selected=name==='changes'?'review':name;state.activePanel=selected??null;setRightPanelOpen(true);
  byId('work-panel-home').hidden=Boolean(selected);for(const view of document.querySelectorAll('[data-panel-view]'))view.hidden=view.dataset.panelView!==selected;
  const titles={review:'审阅',terminal:'终端',browser:'浏览器',files:'文件',chat:'侧边聊天',computer:'桌面控制'};setText('work-panel-title',titles[selected]??'工作面板');
  for(const button of document.querySelectorAll('[data-panel-tab]')){const active=button.dataset.panelTab===selected;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));}
  if(selected==='review'){void refreshGit();void refreshCheckpoints();void refreshIntegrations();}if(selected==='files')void refreshFiles();if(selected==='chat')renderSideChat();if(selected==='terminal'){renderSideTerminal();void openBottomTerminal();}if(selected==='computer')void refreshComputerUse();
}
function computerTargetLabel(target){if(!target)return'尚未检查前台应用';return`${target.name||'未知应用'} · PID ${target.pid} · 身份 ${target.titleHash||'—'}`;}
function renderComputerUse(){const value=state.computerUse??{};setText('computer-support-level',value.supportLevel??'unknown');setText('computer-target',value.locked?`已锁定：${computerTargetLabel(value.target)}`:`前台：${computerTargetLabel(value.foreground)}`);setText('computer-status',value.message??'');byId('computer-controls').hidden=!value.locked;byId('computer-lock').hidden=Boolean(value.locked);byId('computer-unlock').hidden=!value.locked;}
async function refreshComputerUse(){try{const result=operationError(await window.tsukiori.workspace.computerUseStatus());state.computerUse=result.computerUse??{};renderComputerUse();}catch(error){state.computerUse={supportLevel:'unknown',locked:false,message:error.message};renderComputerUse();}}
async function inspectComputerForeground(){try{const result=operationError(await window.tsukiori.workspace.computerUseForeground());state.computerUse={...(state.computerUse??{}),foreground:result.foreground,message:'已读取前台应用；锁定前请确认目标'};renderComputerUse();}catch(error){setText('computer-status',error.message);}}
async function lockComputerUse(){const session=activeSession();if(!session){setText('computer-status','请先选择一个 Agent Session');return;}if(!window.confirm('点击确定后有 2 秒切换到目标应用；后续每个桌面动作仍需再次确认。'))return;setText('computer-status','请在 2 秒内切换到目标应用…');try{const result=operationError(await window.tsukiori.workspace.computerUseAcquire(session.id));state.computerUse=result.computerUse??{};renderComputerUse();}catch(error){setText('computer-status',error.message);}}
async function releaseComputerUse(){try{const result=operationError(await window.tsukiori.workspace.computerUseRelease());state.computerUse=result.computerUse??{};renderComputerUse();}catch(error){setText('computer-status',error.message);}}
async function runComputerAction(action,label){try{const pending=operationError(await window.tsukiori.workspace.computerUseRequest(action));if(!window.confirm(`确认执行 Computer Use：${label}？\n目标：${computerTargetLabel(pending.approval?.target)}`))return;const result=operationError(await window.tsukiori.workspace.computerUseApprove(pending.approval.approvalId));if(result.result?.screenshot){byId('computer-screenshot-image').src=result.result.screenshot.dataUrl;byId('computer-screenshot-frame').hidden=false;}setText('computer-status',`已完成：${label}`);await refreshComputerUse();}catch(error){setText('computer-status',error.message);}}
function computerCoordinates(){return{x:Number(byId('computer-x').value),y:Number(byId('computer-y').value)};}
async function refreshGit() { const session=activeSession(); if(!session)return; try{const result=operationError(await window.tsukiori.workspace.gitStatus(session.id));setText('worktree-path',result.git.worktreePath);renderGitFiles(result.git.files??[]);setText('metric-changes',(result.git.files??[]).length);}catch(error){setText('git-status',error.message);} }
function renderGitFiles(files) { const root=byId('git-files');clear(root);for(const file of files){const label=document.createElement('label');label.className='git-file';const input=document.createElement('input');input.type='checkbox';input.dataset.path=file.path;const status=document.createElement('span');status.className='git-file-status';status.textContent=file.status;const path=document.createElement('span');path.textContent=file.path;label.append(input,status,path);label.addEventListener('click',()=>void loadDiff(file.path));root.append(label);}if(!files.length)root.append(emptyText('暂无改动')); }
async function loadDiff(path){const session=activeSession();if(!session)return;try{const result=operationError(await window.tsukiori.workspace.gitDiff(session.id,path));setText('git-diff',result.diff||'该文件没有 Working Diff');}catch(error){setText('git-diff',error.message);} }
function selectedPaths(){return[...byId('git-files').querySelectorAll('input:checked')].map((input)=>input.dataset.path);}
async function mutateGit(kind){const session=activeSession();if(!session)return;try{operationError(await window.tsukiori.workspace[kind](session.id,selectedPaths()));await refreshGit();}catch(error){setText('git-status',error.message);} }
async function commitFiles(){const session=activeSession();if(!session)return;try{const result=operationError(await window.tsukiori.workspace.commit(session.id,byId('commit-subject').value));setText('git-status','已提交 '+result.sha.slice(0,8));byId('commit-subject').value='';await refreshGit();}catch(error){setText('git-status',error.message);} }

function integrationStatusLabel(status){return({preparing:'准备中',verified:'隔离验证通过',conflicted:'存在冲突',verification_failed:'验证失败',interrupted:'执行中断',promoted:'已 Promotion',discarded:'已丢弃'})[status]??status;}
function shortCommit(value){return typeof value==='string'&&value.length>=8?value.slice(0,8):'—';}
function renderIntegrations(){
  const root=byId('integration-list');if(!root)return;clear(root);const session=activeSession();const target=session?state.integrationTargets.get(session.id):null;
  setText('integration-target-ref',target?.targetRef??(session?'点击刷新读取当前分支':'选择 Session 后读取'));
  setText('integration-target-state',target?`${shortCommit(target.targetCommit)} · 主工作区${target.clean?'干净':'有未提交改动'}`:'—');
  byId('prepare-integration').disabled=!session;
  const items=state.integrations.filter((item)=>item.sessionId===session?.id).sort((a,b)=>b.updatedAt-a.updatedAt);
  for(const item of items){
    const row=document.createElement('article');row.className='integration-row status-'+item.status;
    const head=document.createElement('div');head.className='integration-row-head';const title=document.createElement('strong');title.textContent=`${item.strategy.toUpperCase()} → ${item.targetRef}`;const status=document.createElement('b');status.textContent=integrationStatusLabel(item.status);head.append(title,status);row.append(head);
    const meta=document.createElement('small');meta.textContent=`source ${shortCommit(item.sourceCommit)} · target ${shortCommit(item.targetCommit)}${item.resultCommit?' · result '+shortCommit(item.resultCommit):''}`;row.append(meta);
    if(item.conflictPaths?.length){const conflicts=document.createElement('p');conflicts.className='integration-conflicts';conflicts.textContent=`冲突 ${item.conflictPaths.length} 个：${item.conflictPaths.slice(0,4).join('、')}`;row.append(conflicts);}
    if(item.recoveryRef){const recovery=document.createElement('code');recovery.textContent='恢复引用 '+item.recoveryRef;row.append(recovery);}
    const actions=document.createElement('div');actions.className='integration-actions';
    const addAction=(label,className,handler)=>{const button=document.createElement('button');button.type='button';button.textContent=label;if(className)button.className=className;button.addEventListener('click',handler);actions.append(button);};
    if(item.retained)addAction('打开冲突 Worktree','',()=>void openIntegration(item));
    if(['conflicted','verification_failed','interrupted'].includes(item.status))addAction(item.status==='verification_failed'?'修复后重新验证':'已解决，继续验证','primary',()=>void continueInteractiveIntegration(item));
    if(item.status==='verified')addAction('Promotion 到项目','primary',()=>void promoteIntegration(item));
    if(!['promoted','discarded'].includes(item.status))addAction('丢弃','danger',()=>void discardIntegration(item));
    if(actions.children.length)row.append(actions);root.append(row);
  }
  if(!root.children.length)root.append(emptyText(session?'暂无 Integration；先提交 Session 改动再隔离验证':'请选择 Agent Session'));
}
async function refreshIntegrations(){
  const session=activeSession();if(!session){renderIntegrations();return;}
  try{const [targetResult,listResult]=await Promise.all([window.tsukiori.workspace.integrationTarget(session.id),window.tsukiori.workspace.listIntegrations(session.id)]);const target=operationError(targetResult).target;const integrations=operationError(listResult).integrations??[];state.integrationTargets.set(session.id,target);state.integrations=[...state.integrations.filter((item)=>item.sessionId!==session.id),...integrations];setText('integration-status','');renderIntegrations();}catch(error){setText('integration-status',error.message);renderIntegrations();}
}
async function prepareIntegration(){
  const session=activeSession();if(!session)return;let target=state.integrationTargets.get(session.id);
  if(!target){await refreshIntegrations();target=state.integrationTargets.get(session.id);if(!target)return;}
  setText('integration-status','正在创建隔离 Integration Worktree…');byId('prepare-integration').disabled=true;
  try{const result=operationError(await window.tsukiori.workspace.prepareIntegration(session.id,byId('integration-strategy').value,target.targetRef));state.integrations=[result.integration,...state.integrations.filter((item)=>item.id!==result.integration.id)];setText('integration-status',result.integration.status==='verified'?'隔离验证通过；主工作区尚未修改':integrationStatusLabel(result.integration.status));renderIntegrations();}catch(error){setText('integration-status',error.message);}finally{byId('prepare-integration').disabled=false;}
}
async function continueInteractiveIntegration(item){
  const session=activeSession();if(!session)return;setText('integration-status','正在继续并验证冲突结果…');
  try{operationError(await window.tsukiori.workspace.continueInteractiveIntegration(session.id,item.id));await refreshIntegrations();}catch(error){setText('integration-status',error.message);await refreshIntegrations();}
}
async function promoteIntegration(item){
  const session=activeSession();if(!session)return;const message=`Promotion 会把已验证结果 ${shortCommit(item.resultCommit)} 快进到项目分支 ${item.targetRef}。\n\n主工作区必须干净且 HEAD 未变化；操作前会创建 refs/tsukiori/recovery 恢复引用。确认继续？`;if(!window.confirm(message))return;setText('integration-status','正在 Promotion，并创建恢复引用…');
  try{const result=operationError(await window.tsukiori.workspace.promoteIntegration(session.id,item.id));setText('integration-status',`已 Promotion · 恢复引用 ${result.integration.recoveryRef}`);await refreshIntegrations();await refreshGit();}catch(error){setText('integration-status',error.message);await refreshIntegrations();}
}
async function discardIntegration(item){
  const session=activeSession();if(!session||!window.confirm('丢弃此 Integration？保留的冲突 Worktree 和 Integration 分支会被删除，Session Worktree 不受影响。'))return;
  try{operationError(await window.tsukiori.workspace.discardIntegration(session.id,item.id));setText('integration-status','Integration 已丢弃');await refreshIntegrations();}catch(error){setText('integration-status',error.message);}
}
async function openIntegration(item){const session=activeSession();if(!session)return;try{operationError(await window.tsukiori.workspace.openIntegration(session.id,item.id));}catch(error){setText('integration-status',error.message);}}

function capabilityItem(title,detail,badge=''){const row=document.createElement('article');row.className='capability-list-item';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:title}),Object.assign(document.createElement('small'),{textContent:detail}));const status=document.createElement('b');status.textContent=badge;row.append(box,status);return row;}
function diagnosticTile(label,value){const tile=document.createElement('article');tile.className='diagnostic-tile';tile.append(Object.assign(document.createElement('span'),{textContent:label}),Object.assign(document.createElement('strong'),{textContent:String(value)}));return tile;}
function renderNativeSettings(){
  const native=state.nativeCapabilities??{};const skills=byId('skill-settings-list'),mcp=byId('mcp-settings-list');if(!skills||!mcp)return;clear(skills);clear(mcp);
  for(const skill of native.skills??[])skills.append(capabilityItem(skill.name,skill.description||skill.scope,skill.enabled?'已启用':'已停用'));
  for(const server of native.servers??[])mcp.append(capabilityItem(server.name,`${server.toolCount} Tools · ${server.resourceCount} Resources`,server.authStatus));
  if(!skills.children.length)skills.append(emptyText('当前 Session 没有可展示的 Skills'));if(!mcp.children.length)mcp.append(emptyText('当前 Session 没有配置 MCP Server'));
}
async function refreshNativeSettings(){await loadCodexNative();renderNativeSettings();}
function renderMcpSettings(){const root=byId('mcp-settings-list');if(!root)return;clear(root);for(const server of state.mcpServers??[]){const health=(state.extensionHealth?.mcp??[]).find((item)=>item.id===server.id);const row=document.createElement('article');row.className='mcp-server-row';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:server.name}),Object.assign(document.createElement('small'),{textContent:`${server.scope} · ${server.transport} · ${server.authStatus} · Runtime ${health?.runtimePresence??'未检查'}`}));const actions=document.createElement('div');if(health)actions.append(Object.assign(document.createElement('b'),{textContent:health.health}));const edit=document.createElement('button');edit.type='button';edit.textContent='编辑';edit.addEventListener('click',()=>editMcp(server));const remove=document.createElement('button');remove.type='button';remove.className='danger';remove.textContent='删除';remove.addEventListener('click',async()=>{if(!window.confirm('删除这个 MCP 配置？'))return;try{operationError(await window.tsukiori.workspace.deleteMcp(server.id));await refreshMcpSettings();}catch(error){setText('mcp-editor-status',error.message);}});actions.append(edit,remove);row.append(box,actions);root.append(row);}for(const server of state.extensionHealth?.mcp??[]){if(server.configured)continue;root.append(capabilityItem(server.name,`runtime only · ${server.toolCount} Tools · ${server.resourceCount} Resources`,server.health));}if(!root.children.length)root.append(emptyText('尚未配置 MCP Server'));}
async function refreshMcpSettings(){try{const result=operationError(await window.tsukiori.workspace.listMcp(activeProject()?.id));state.mcpServers=result.servers??[];renderMcpSettings();}catch(error){const root=byId('mcp-settings-list');clear(root);root.append(emptyText(error.message));}}
function newMcp(){state.selectedMcpId=null;byId('mcp-editor').hidden=false;byId('mcp-name').value='';byId('mcp-scope').value=activeProject()?'project':'user';byId('mcp-transport').value='stdio';byId('mcp-command-url').value='';byId('mcp-args').value='';byId('mcp-env-keys').value='';setText('mcp-editor-status','');}
function editMcp(server){state.selectedMcpId=server.id;byId('mcp-editor').hidden=false;byId('mcp-name').value=server.name;byId('mcp-scope').value=server.scope;byId('mcp-transport').value=server.transport;byId('mcp-command-url').value=server.transport==='stdio'?(server.command??''):(server.url??'');byId('mcp-args').value=(server.args??[]).join('\n');byId('mcp-env-keys').value=(server.envKeys??[]).join('\n');setText('mcp-editor-status','正在编辑 '+server.name);}
async function saveMcp(){try{const transport=byId('mcp-transport').value;const result=operationError(await window.tsukiori.workspace.saveMcp({id:state.selectedMcpId||undefined,name:byId('mcp-name').value,scope:byId('mcp-scope').value,projectId:activeProject()?.id,transport, ...(transport==='stdio'?{command:byId('mcp-command-url').value}:{url:byId('mcp-command-url').value}),args:byId('mcp-args').value.split(/\r?\n/).map((value)=>value.trim()).filter(Boolean),envKeys:byId('mcp-env-keys').value.split(/\r?\n/).map((value)=>value.trim()).filter(Boolean)}));state.selectedMcpId=result.server.id;setText('mcp-editor-status','已保存到本机');await refreshMcpSettings();}catch(error){setText('mcp-editor-status',error.message);}}
function renderSkillsSettings(){const root=byId('skill-settings-list');if(!root)return;clear(root);for(const skill of state.skills??[]){const health=(state.extensionHealth?.skills??[]).find((item)=>item.name.toLocaleLowerCase()===skill.name.toLocaleLowerCase()&&item.configured);const row=document.createElement('article');row.className='skill-server-row';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:skill.name}),Object.assign(document.createElement('small'),{textContent:`${skill.scope} · ${skill.files} files · ${skill.safety} · Runtime ${health?.runtimePresence??'未检查'} · ${skill.description}`}));const actions=document.createElement('div');if(health)actions.append(Object.assign(document.createElement('b'),{textContent:health.health}));const detail=document.createElement('button');detail.type='button';detail.textContent='详情';detail.addEventListener('click',()=>void showSkillDetail(skill));actions.append(detail);if(skill.scope==='project'){const remove=document.createElement('button');remove.type='button';remove.className='danger';remove.textContent='卸载';remove.addEventListener('click',async()=>{try{operationError(await window.tsukiori.workspace.uninstallSkill(activeProject().id,skill.name));await refreshSkillsSettings();}catch(error){setText('skill-settings-status',error.message);}});actions.append(remove);}row.append(box,actions);root.append(row);}for(const skill of state.extensionHealth?.skills??[]){if(skill.configured)continue;root.append(capabilityItem(skill.name,`runtime only · ${skill.runtimeScope} · ${skill.description||''}`,skill.health));}if(!root.children.length)root.append(emptyText('当前项目未发现 Skill'));}
async function refreshSkillsSettings(){const project=activeProject();if(!project){state.skills=[];renderSkillsSettings();return;}try{const result=operationError(await window.tsukiori.workspace.listSkills(project.id));state.skills=result.skills??[];renderSkillsSettings();setText('skill-settings-status',`已扫描 ${state.skills.length} 个 Skill`);}catch(error){setText('skill-settings-status',error.message);}}
async function showSkillDetail(skill){try{const result=operationError(await window.tsukiori.workspace.skillDetail(activeProject().id,skill.id));const detail=byId('skill-settings-detail');detail.hidden=false;detail.textContent=`${result.skill.name}\n${result.skill.description}\n\n${result.skill.content}`;}catch(error){setText('skill-settings-status',error.message);}}
async function importSkill(){const project=activeProject();if(!project){setText('skill-settings-status','请先添加并选择项目');return;}try{const picked=operationError(await window.tsukiori.workspace.pickSkillSource());if(picked.canceled)return;operationError(await window.tsukiori.workspace.installSkill(project.id,picked.sourcePath));await refreshSkillsSettings();setText('skill-settings-status','Skill 已导入到 .claude/skills');}catch(error){setText('skill-settings-status',error.message);}}
function renderAgentSettings(){const summary=byId('agent-settings-summary'),list=byId('agent-settings-list');if(!summary||!list)return;clear(summary);clear(list);summary.append(diagnosticTile('Runtime',state.runtimes.filter((item)=>item.available).length),diagnosticTile('Agent Team',state.teams.length),diagnosticTile('运行中',state.teams.filter((item)=>item.status==='running').length));for(const runtime of state.runtimes)list.append(capabilityItem(runtime.name,(runtime.capabilities??[]).join(' · ')||runtime.error||'未声明能力',runtime.available?runtime.supportLevel:'不可用'));for(const team of state.teams)list.append(capabilityItem(team.name,`${team.memberSessionIds.length} Agent · ${new Date(team.updatedAt).toLocaleString()}`,team.status));void refreshAgentActivity();}
async function refreshAgentActivity(){const root=byId('agent-activity-list');if(!root)return;try{const result=operationError(await window.tsukiori.workspace.activity(state.activeSessionId||undefined));clear(root);for(const task of result.activity?.backgroundTasks??[]){const row=document.createElement('article');row.className='capability-list-item';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:task.title}),Object.assign(document.createElement('small'),{textContent:`Session · ${task.status} · ${new Date(task.startedAt).toLocaleTimeString()}`}));const stop=document.createElement('button');stop.type='button';stop.textContent='停止';stop.addEventListener('click',async()=>{try{operationError(await window.tsukiori.workspace.stopBackgroundTask(task.id));await refreshAgentActivity();}catch(error){setText('agent-activity-list',error.message);}});row.append(box,stop);root.append(row);}for(const agent of result.activity?.subagents??[]){root.append(capabilityItem(agent.role||'Subagent',`${agent.source==='team'?'Tsukiori Team':'Runtime 原生'} · ${agent.parentId?'parent '+agent.parentId+' · ':''}${new Date(agent.updatedAt??agent.startedAt).toLocaleTimeString()}`,agent.status));}if(!root.children.length)root.append(emptyText('暂无后台 Session 或 Subagent Activity'));}catch(error){clear(root);root.append(emptyText(error.message));}}
function renderMemorySettings(){const select=byId('memory-project-select'),root=byId('memory-settings-list');if(!select||!root)return;clear(select);for(const project of state.projects)appendOption(select,project.id,project.name,project.id===state.activeProjectId);clear(root);for(const file of state.memoryFiles??[]){const row=document.createElement('article');row.className='memory-file-row';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:file.path}),Object.assign(document.createElement('small'),{textContent:`${formatBytes(file.size)} · ${new Date(file.updatedAt).toLocaleString()}`}));const open=document.createElement('button');open.type='button';open.textContent='打开';open.addEventListener('click',()=>loadMemory(file.path));row.append(box,open);root.append(row);}if(!root.children.length)root.append(emptyText('当前项目没有 Memory 文件'));}
async function refreshMemorySettings(){const project=activeProject();if(!project){state.memoryFiles=[];renderMemorySettings();return;}try{const result=operationError(await window.tsukiori.workspace.listMemory(project.id));state.memoryFiles=result.files??[];renderMemorySettings();}catch(error){setText('memory-settings-status',error.message);}}
async function loadMemory(path){try{const result=operationError(await window.tsukiori.workspace.readMemory(activeProject().id,path));byId('memory-path').value=result.file.path;byId('memory-content').value=result.file.content;setText('memory-settings-status','已读取');}catch(error){setText('memory-settings-status',error.message);}}
async function saveMemory(){try{const result=operationError(await window.tsukiori.workspace.saveMemory(activeProject().id,byId('memory-path').value,byId('memory-content').value));setText('memory-settings-status','已保存 '+result.file.path);await refreshMemorySettings();}catch(error){setText('memory-settings-status',error.message);}}
function renderScheduledTasks(){const root=byId('scheduled-task-list');if(!root)return;clear(root);for(const task of state.scheduledTasks??[]){const row=document.createElement('article');row.className='mcp-server-row';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:task.name}),Object.assign(document.createElement('small'),{textContent:`每 ${task.intervalMinutes} 分钟 · ${task.enabled?'已启用':'已停用'} · ${task.lastError||'下次 '+new Date(task.nextRunAt).toLocaleString()}`}));const actions=document.createElement('div');const toggle=document.createElement('button');toggle.type='button';toggle.textContent=task.enabled?'停用':'启用';toggle.addEventListener('click',async()=>{try{operationError(await window.tsukiori.workspace.setScheduledTaskEnabled(task.id,!task.enabled));await refreshScheduledTasks();}catch(error){setText('scheduled-task-status',error.message);}});const run=document.createElement('button');run.type='button';run.textContent='立即运行';run.addEventListener('click',async()=>{setText('scheduled-task-status','正在启动任务…');try{operationError(await window.tsukiori.workspace.runScheduledTask(task.id));setText('scheduled-task-status','任务已提交到 Session');await refreshScheduledTasks();}catch(error){setText('scheduled-task-status',error.message);}});const remove=document.createElement('button');remove.type='button';remove.className='danger';remove.textContent='删除';remove.addEventListener('click',async()=>{try{operationError(await window.tsukiori.workspace.deleteScheduledTask(task.id));await refreshScheduledTasks();}catch(error){setText('scheduled-task-status',error.message);}});actions.append(toggle,run,remove);row.append(box,actions);root.append(row);}if(!root.children.length)root.append(emptyText('尚未创建定时任务'));}
async function refreshScheduledTasks(){try{const result=operationError(await window.tsukiori.workspace.listScheduledTasks(activeProject()?.id));state.scheduledTasks=result.tasks??[];renderScheduledTasks();}catch(error){setText('scheduled-task-status',error.message);}}
function newScheduledTask(){state.selectedScheduledTaskId=null;const select=byId('scheduled-task-project');clear(select);for(const project of state.projects)appendOption(select,project.id,project.name,project.id===state.activeProjectId);byId('scheduled-task-name').value='';byId('scheduled-task-interval').value='60';byId('scheduled-task-enabled').checked=false;byId('scheduled-task-prompt').value='';byId('scheduled-task-editor').hidden=false;}
async function saveScheduledTask(){try{const result=operationError(await window.tsukiori.workspace.saveScheduledTask({id:state.selectedScheduledTaskId||undefined,name:byId('scheduled-task-name').value,projectId:byId('scheduled-task-project').value,prompt:byId('scheduled-task-prompt').value,intervalMinutes:Number(byId('scheduled-task-interval').value),enabled:byId('scheduled-task-enabled').checked}));state.selectedScheduledTaskId=result.task.id;byId('scheduled-task-editor').hidden=true;setText('scheduled-task-status','任务已保存');await refreshScheduledTasks();}catch(error){setText('scheduled-task-status',error.message);}}
function renderTraceSettings(){const summary=byId('trace-summary'),list=byId('trace-settings-list');if(!summary||!list)return;clear(summary);clear(list);const events=state.recentEvents??[];summary.append(diagnosticTile('事件',events.length),diagnosticTile('错误',events.filter((item)=>item.type==='runtime.error').length),diagnosticTile('Tool',events.filter((item)=>item.type==='tool.event').length),diagnosticTile('Turn',events.filter((item)=>item.type==='turn.completed').length));for(const event of [...events].reverse().slice(0,100)){const row=document.createElement('article');row.className='trace-item';const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:event.type}),Object.assign(document.createElement('small'),{textContent:String(event.payload?.status??event.payload?.tool??event.payload?.action??'本机事件')}));row.append(box,Object.assign(document.createElement('time'),{textContent:new Date(event.createdAt).toLocaleTimeString()}));list.append(row);}if(!list.children.length)list.append(emptyText('暂无 Trace 事件'));}
async function runDoctor(){setText('diagnostic-settings-detail','正在检查 Runtime、Provider 与事件链路…');try{const result=operationError(await window.tsukiori.workspace.diagnosticSummary());const diagnostic=result.diagnostic;const summary=byId('diagnostic-settings-summary');clear(summary);summary.append(diagnosticTile('项目',diagnostic.projects),diagnosticTile('Session',diagnostic.sessions),diagnosticTile('运行中',diagnostic.activeSessions),diagnosticTile('失败',diagnostic.failedSessions));setText('diagnostic-settings-detail',JSON.stringify(diagnostic,null,2));}catch(error){setText('diagnostic-settings-detail',error.message);}}
async function exportDiagnosticSettings(){try{const result=operationError(await window.tsukiori.workspace.exportDiagnostic(false));setText('diagnostic-export-status',result.canceled?'已取消':'已导出脱敏诊断包');}catch(error){setText('diagnostic-export-status',error.message);}}

const settingsMeta={general:['通用','启动行为、语言、更新与默认工作方式'],appearance:['外观','主题、界面密度与动态效果'],account:['账号','本地身份与 Runtime 授权状态'],agent:['Provider','Runtime、Provider、模型与 API Key'],terminal:['终端','Shell、ConPTY 与本地执行环境'],mcp:['MCP 服务','宿主配置 Scope 与当前 Runtime 实际观察'],agents:['Agents','本地 Runtime 与 Agent Team'],skills:['已安装技能','项目扫描结果与当前 Runtime 可见性'],memory:['项目记忆','本机 Transcript、Session 与 Worktree 绑定'],scheduled:['定时任务','本地计划任务与隔离 Runtime Turn'],usage:['Token 用量','本机 Session 与 Turn 统计'],trace:['Trace','本机脱敏 Agent 事件时间线'],diagnostics:['诊断','Runtime、Provider、事件与安全边界'],projects:['项目','项目默认规则与本地工作区'],devices:['设备','本机 Runtime 与执行环境'],github:['GitHub','本地 Git 与远程凭据边界'],shortcuts:['键盘快捷键','全局与工作区快捷键'],billing:['账单','Provider 直接结算说明'],about:['关于','版本、开源组件与诊断导出']};
function openSettings(page='general'){showDialog(byId('settings-dialog'));showSettingsPage(page);renderSettingsData();}
function showSettingsPage(page){for(const button of byId('settings-nav').querySelectorAll('button'))button.classList.toggle('active',button.dataset.settingsPage===page);for(const view of document.querySelectorAll('[data-settings-view]'))view.hidden=view.dataset.settingsView!==page;setText('settings-title',settingsMeta[page][0]);setText('settings-subtitle',settingsMeta[page][1]);}
function renderSettingsData(){const s=state.settings??{};byId('setting-language').value=s.language??'zh-CN';byId('setting-auto-update').checked=s.autoUpdate!==false;byId('setting-start-minimized').checked=s.startMinimized===true;byId('setting-persist-conversation').checked=s.persistConversation!==false;byId('setting-confirm-high-risk').checked=s.confirmHighRisk!==false;byId('setting-theme').value=s.theme??'light';byId('setting-density').value=s.density??'comfortable';byId('setting-reduce-motion').checked=s.reduceMotion===true;byId('setting-terminal-shell').value=s.terminalShell??'powershell';fillRuntime(byId('setting-default-runtime'),s.defaultRuntime??'codex');fillProvider(byId('setting-default-provider'),byId('setting-default-runtime').value,s.defaultProviderId);renderProviderList();renderSettingsRuntimes();renderSettingsProjects();renderCcHahaImport();renderUsage();renderAgentSettings();renderMemorySettings();renderTraceSettings();renderNativeSettings();renderMcpSettings();renderScheduledTasks();void refreshSkillsSettings();void refreshMemorySettings();void refreshScheduledTasks();setText('about-version','Desktop '+(state.versions.desktop??'—')+' · Protocol '+(state.versions.protocol??'—'));}
function renderProviderList(){const root=byId('provider-settings-list');clear(root);for(const provider of state.providers){const button=document.createElement('button');button.type='button';button.className='provider-list-item'+(provider.id===state.selectedProviderId?' active':'');const icon=document.createElement('span');icon.className='provider-icon';icon.textContent=provider.name.slice(0,1).toUpperCase();const text=document.createElement('span');const strong=document.createElement('strong');strong.textContent=provider.name;const small=document.createElement('small');small.textContent=provider.kind+' · '+(provider.hasSecret||provider.kind==='chatgpt'||provider.kind==='claude-native'?'已配置':'需要 API Key');text.append(strong,small);const status=document.createElement('b');status.textContent=provider.lastTest?.ok?'已连接':'›';button.append(icon,text,status);button.addEventListener('click',()=>selectProviderEditor(provider.id));root.append(button);}if(!state.selectedProviderId&&state.providers[0])selectProviderEditor(state.providers[0].id,false);}
function selectProviderEditor(id,rerender=true){state.selectedProviderId=id;const p=providerById(id);if(!p)return;byId('provider-id').value=p.id;byId('provider-name').value=p.name;if(p.kind==='chatgpt'&&![...byId('provider-kind').options].some((option)=>option.value==='chatgpt'))appendOption(byId('provider-kind'),'chatgpt','ChatGPT 登录');if(p.kind==='claude-native'&&![...byId('provider-kind').options].some((option)=>option.value==='claude-native'))appendOption(byId('provider-kind'),'claude-native','Claude 本机登录');byId('provider-kind').value=p.kind;byId('provider-base-url').value=p.baseUrl;byId('provider-models').value=(p.models??[]).join(', ');byId('provider-api-key').value='';byId('provider-api-key').placeholder=p.kind==='claude-native'?'使用 Claude Code 本机认证，不读取 API Key':p.hasSecret?'已保存，留空则保持不变':'输入 API Key';byId('delete-provider').disabled=p.kind==='chatgpt'||p.kind==='claude-native';setText('provider-editor-title',p.name);setText('provider-editor-status',p.lastTest?`${p.lastTest.ok?'连接成功':'连接失败'} · ${p.lastTest.latencyMs} ms · ${p.lastTest.category}`:'');if(rerender)renderProviderList();}
function newProvider(){state.selectedProviderId=null;byId('provider-id').value='';byId('provider-name').value='自定义 Provider';byId('provider-kind').value='openai-compatible';byId('provider-base-url').value='https://';byId('provider-models').value='';byId('provider-api-key').value='';byId('delete-provider').disabled=true;setText('provider-editor-title','添加 Provider');setText('provider-editor-status','');}
async function saveProvider(){try{const models=byId('provider-models').value.split(',').map((v)=>v.trim()).filter(Boolean);const result=operationError(await window.tsukiori.workspace.saveProvider({id:byId('provider-id').value||undefined,name:byId('provider-name').value,kind:byId('provider-kind').value,baseUrl:byId('provider-base-url').value,models,apiKey:byId('provider-api-key').value||undefined,enabled:true}));state.selectedProviderId=result.provider.id;setText('provider-editor-status','已安全保存');await reloadSnapshot();}catch(error){setText('provider-editor-status',error.message);} }
async function testProvider(){const id=byId('provider-id').value;if(!id){setText('provider-editor-status','请先保存 Provider');return;}setText('provider-editor-status','正在测试连接…');try{const result=operationError(await window.tsukiori.workspace.testProvider(id));setText('provider-editor-status',`${result.test.ok?'连接成功':'连接失败'} · ${result.test.latencyMs} ms · ${result.test.category}`);await reloadSnapshot();}catch(error){setText('provider-editor-status',error.message);} }
async function fetchProviderModels(){const id=byId('provider-id').value;if(!id){setText('provider-editor-status','请先保存 Provider 与 API Key');return;}setText('provider-editor-status','正在从 Provider 获取模型…');try{const result=operationError(await window.tsukiori.workspace.listProviderModels(id));byId('provider-models').value=(result.models??[]).join(', ');setText('provider-editor-status',`已获取 ${result.models?.length??0} 个模型 · ${result.source}`);}catch(error){setText('provider-editor-status',error.message);} }
async function deleteProvider(){const id=byId('provider-id').value;if(!id)return;try{operationError(await window.tsukiori.workspace.deleteProvider(id));state.selectedProviderId=null;newProvider();await reloadSnapshot();}catch(error){setText('provider-editor-status',error.message);} }
function renderSettingsRuntimes(){for(const id of ['settings-runtime-list','device-runtime-list']){const root=byId(id);if(!root)continue;clear(root);for(const runtime of state.runtimes){const row=document.createElement('div');row.className='settings-runtime-item';const orb=document.createElement('span');orb.className='runtime-orb '+(runtime.type==='claude'?'claude':'codex');orb.textContent=runtime.type.slice(0,1).toUpperCase();const box=document.createElement('div');box.append(Object.assign(document.createElement('strong'),{textContent:runtime.name}),Object.assign(document.createElement('small'),{textContent:runtime.version+' · '+runtime.source+' · '+(runtime.authenticated?runtime.authSource:'未登录 / Provider API')}));const level=document.createElement('b');level.textContent=runtime.available?runtime.supportLevel:'不可用';row.append(orb,box,level);root.append(row);}}}
function renderSettingsProjects(){const root=byId('settings-project-list');clear(root);for(const project of state.projects){const row=document.createElement('div');row.className='setting-row';const box=document.createElement('span');box.append(Object.assign(document.createElement('strong'),{textContent:project.name}),Object.assign(document.createElement('small'),{textContent:project.gitRoot}));const remove=document.createElement('button');remove.type='button';remove.textContent='移除';remove.addEventListener('click',async()=>{if(!window.confirm('从 Tsukiori 列表移除此项目？不会删除本地文件。'))return;try{operationError(await window.tsukiori.workspace.removeProject(project.id));await reloadSnapshot();}catch(error){setText('settings-save-status',error.message);}});row.append(box,remove);root.append(row);}if(!state.projects.length)root.append(emptyText('尚未添加项目'));}
function renderCcHahaImport(){const root=byId('cc-haha-import-list'),scan=state.ccHahaImportScan;clear(root);if(!scan){root.append(emptyText('Dry Run 后显示可导入 Session'));byId('run-cc-haha-import').disabled=true;return;}for(const session of scan.sessions){const row=document.createElement('label');row.className='setting-row';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.dataset.candidateId=session.candidateId;checkbox.checked=session.importable&&!session.alreadyImported;checkbox.disabled=!session.importable||session.alreadyImported;const box=document.createElement('span');const status=session.alreadyImported?'已导入':session.importable?'可导入':'不可导入';box.append(Object.assign(document.createElement('strong'),{textContent:session.title}),Object.assign(document.createElement('small'),{textContent:`${status} · ${session.messageCount} 条消息 · ${formatBytes(session.bytes)} · ${session.projectRoot??session.warnings?.join('；')??'未验证项目'}`}));row.append(checkbox,box);root.append(row);}if(!scan.sessions.length)root.append(emptyText('未发现 UUID JSONL Transcript'));byId('run-cc-haha-import').disabled=scan.importableCount<1;setText('cc-haha-import-summary',`Dry Run：${scan.transcriptCount} 个 Transcript，${scan.importableCount} 个待导入，${scan.alreadyImportedCount} 个已导入；源目录保持只读。`);}
async function pickCcHahaSource(){try{const result=operationError(await window.tsukiori.workspace.pickCcHahaSource());if(result.canceled)return;byId('cc-haha-source').value=result.sourcePath;state.ccHahaImportScan=null;renderCcHahaImport();setText('cc-haha-import-summary','已选择目录；请运行只读 Dry Run。');}catch(error){setText('cc-haha-import-summary',error.message);}}
async function scanCcHahaImport(){const sourcePath=byId('cc-haha-source').value.trim();if(!sourcePath){setText('cc-haha-import-summary','请先选择 cc-haha / Claude 配置目录');return;}try{setText('cc-haha-import-summary','正在只读扫描并验证 Transcript 与 Git 根目录…');const result=operationError(await window.tsukiori.workspace.scanCcHahaImport(sourcePath));state.ccHahaImportScan=result.scan;renderCcHahaImport();}catch(error){state.ccHahaImportScan=null;renderCcHahaImport();setText('cc-haha-import-summary',error.message);}}
async function runCcHahaImport(){const scan=state.ccHahaImportScan;if(!scan)return;const candidateIds=[...byId('cc-haha-import-list').querySelectorAll('input:checked')].map((input)=>input.dataset.candidateId);if(!candidateIds.length){setText('cc-haha-import-summary','请至少选择一个可导入 Session');return;}if(!window.confirm(`将导入 ${candidateIds.length} 个 Session。\n\n源目录不会被修改；导入历史保持只读，只能通过显式 Fork 继续。失败时整批回滚。\n\n确认继续？`))return;try{byId('run-cc-haha-import').disabled=true;setText('cc-haha-import-summary','正在创建隔离 Worktree 并导入脱敏历史…');const result=operationError(await window.tsukiori.workspace.importCcHaha(byId('cc-haha-source').value,scan.sourceFingerprint,candidateIds));state.ccHahaImportScan=null;await reloadSnapshot();renderCcHahaImport();setText('cc-haha-import-summary',`已导入 ${result.result.importedCount} 个只读 Session；请从会话列表查看或 Fork。`);}catch(error){await reloadSnapshot().catch(()=>undefined);byId('run-cc-haha-import').disabled=false;setText('cc-haha-import-summary',error.message);}}
function renderUsage(){setText('usage-turns',state.usage.turnCount??0);setText('usage-sessions',state.usage.sessionCount??0);const root=byId('usage-bars');clear(root);const values=Object.entries(state.usage.byRuntime??{});const max=Math.max(1,...values.map(([,v])=>v));for(const [runtime,count]of values){const row=document.createElement('div');row.className='usage-bar';const label=document.createElement('span');label.textContent=runtime;const bar=document.createElement('i');bar.style.setProperty('--value',Math.round(count/max*100)+'%');const value=document.createElement('b');value.textContent=String(count);row.append(label,bar,value);root.append(row);}if(!values.length)root.append(emptyText('暂无用量数据'));}
async function saveSettings(){try{const result=operationError(await window.tsukiori.workspace.updateSettings({language:byId('setting-language').value,autoUpdate:byId('setting-auto-update').checked,startMinimized:byId('setting-start-minimized').checked,persistConversation:byId('setting-persist-conversation').checked,confirmHighRisk:byId('setting-confirm-high-risk').checked,theme:byId('setting-theme').value,density:byId('setting-density').value,reduceMotion:byId('setting-reduce-motion').checked,defaultRuntime:byId('setting-default-runtime').value,defaultProviderId:byId('setting-default-provider').value,terminalShell:byId('setting-terminal-shell').value}));state.settings=result.settings;applyAppearance();setText('settings-save-status','已保存到本机');}catch(error){setText('settings-save-status',error.message);} }
async function checkUpdates(){setText('update-status','正在检查…');try{const result=operationError(await window.tsukiori.workspace.checkUpdates());setText('update-status',result.update.available?`发现 ${result.update.latest} · 当前 ${result.update.current}`:`已是最新版本 ${result.update.current}`);}catch(error){setText('update-status',error.message);} }
function applyAppearance(){document.body.classList.toggle('density-compact',state.settings.density==='compact');document.body.classList.toggle('reduce-motion',state.settings.reduceMotion===true);const width=Math.max(260,Math.min(720,Number(state.settings.workPanelWidth)||360));const terminalHeight=Math.max(120,Math.min(560,Number(state.settings.terminalHeight)||220));document.documentElement.style.setProperty('--work-panel-width',width+'px');document.documentElement.style.setProperty('--terminal-height',terminalHeight+'px');byId('work-panel-resizer')?.setAttribute('aria-valuenow',String(width));byId('terminal-resizer')?.setAttribute('aria-valuenow',String(terminalHeight));}

function setupWorkPanelResize(){
  const shell=document.querySelector('.app-shell'),handle=byId('work-panel-resizer');if(!shell||!handle)return;
  let startX=0,startWidth=360,current=360;
  const maximum=()=>Math.max(260,Math.min(720,window.innerWidth-720));
  const apply=(value)=>{current=Math.max(260,Math.min(maximum(),Math.round(value)));document.documentElement.style.setProperty('--work-panel-width',current+'px');handle.setAttribute('aria-valuenow',String(current));};
  const persist=async()=>{shell.classList.remove('resizing-panel');state.settings.workPanelWidth=current;try{const result=operationError(await window.tsukiori.workspace.updateSettings({workPanelWidth:current}));state.settings=result.settings;}catch(error){setText('turn-status',error.message);}};
  handle.addEventListener('pointerdown',(event)=>{if(event.button!==0)return;startX=event.clientX;startWidth=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--work-panel-width'),10)||360;current=startWidth;shell.classList.remove('right-collapsed');shell.classList.add('resizing-panel');handle.setPointerCapture(event.pointerId);event.preventDefault();});
  handle.addEventListener('pointermove',(event)=>{if(shell.classList.contains('resizing-panel'))apply(startWidth+(startX-event.clientX));});
  handle.addEventListener('pointerup',(event)=>{if(!shell.classList.contains('resizing-panel'))return;handle.releasePointerCapture(event.pointerId);void persist();});
  handle.addEventListener('pointercancel',()=>{if(shell.classList.contains('resizing-panel'))void persist();});
  handle.addEventListener('dblclick',()=>{apply(360);void persist();});
  handle.addEventListener('keydown',(event)=>{if(!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;const value=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--work-panel-width'),10)||360;apply(event.key==='Home'?360:value+(event.key==='ArrowLeft'?16:-16));void persist();event.preventDefault();});
}

function setupTerminalResize(){
  const shell=document.querySelector('.app-shell'),handle=byId('terminal-resizer');if(!shell||!handle)return;
  let startY=0,startHeight=220,current=220;
  const maximum=()=>Math.max(120,Math.min(560,window.innerHeight-280));
  const apply=(value)=>{current=Math.max(120,Math.min(maximum(),Math.round(value)));document.documentElement.style.setProperty('--terminal-height',current+'px');handle.setAttribute('aria-valuenow',String(current));};
  const persist=async()=>{shell.classList.remove('resizing-terminal');state.settings.terminalHeight=current;try{const result=operationError(await window.tsukiori.workspace.updateSettings({terminalHeight:current}));state.settings=result.settings;}catch(error){setText('turn-status',error.message);}};
  handle.addEventListener('pointerdown',(event)=>{if(event.button!==0)return;startY=event.clientY;startHeight=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--terminal-height'),10)||220;current=startHeight;setTerminalOpen(true);shell.classList.add('resizing-terminal');handle.setPointerCapture(event.pointerId);event.preventDefault();});
  handle.addEventListener('pointermove',(event)=>{if(shell.classList.contains('resizing-terminal'))apply(startHeight+(startY-event.clientY));});
  handle.addEventListener('pointerup',(event)=>{if(!shell.classList.contains('resizing-terminal'))return;handle.releasePointerCapture(event.pointerId);void persist();});
  handle.addEventListener('pointercancel',()=>{if(shell.classList.contains('resizing-terminal'))void persist();});
  handle.addEventListener('dblclick',()=>{apply(220);void persist();});
  handle.addEventListener('keydown',(event)=>{if(!['ArrowUp','ArrowDown','Home'].includes(event.key))return;const value=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--terminal-height'),10)||220;apply(event.key==='Home'?220:value+(event.key==='ArrowUp'?16:-16));void persist();event.preventDefault();});
}

